import type { Metadata } from "next";
import { site } from "@/content/site";
import { allowIndexing, siteUrl } from "@/lib/env";

/** Default share image (generated by app/opengraph-image.tsx). */
export const ogImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${site.name}: ${site.tagline}`,
};

type PageMetaInput = {
  /** Short page title; the layout template appends " | Kertz Digital". */
  title: string;
  /** ≤155 characters, ideally ending in a call to action. */
  description: string;
  /** Route path, e.g. "/pricing". Used for canonical + og:url. */
  path: string;
  /** Set true for pages that shouldn't be indexed (thank-you pages etc.). */
  noindex?: boolean;
};

/**
 * Builds a page's full metadata in one call.
 * Next.js merges metadata shallowly, so a page that sets `openGraph` replaces
 * the layout's entire `openGraph` object. Building it here keeps every page
 * complete and consistent, including the share image (which would otherwise
 * only reach the homepage).
 */
export function pageMetadata({
  title,
  description,
  path,
  noindex,
}: PageMetaInput): Metadata {
  const fullTitle = path === "/" ? title : `${title} | ${site.name}`;
  return {
    title: path === "/" ? { absolute: title } : title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      locale: "en_US",
      siteName: site.name,
      url: path,
      title: fullTitle,
      description,
      images: [ogImage],
    },
    twitter: {
      card: "summary_large_image",
      title: fullTitle,
      description,
      images: [ogImage],
    },
    ...((noindex || !allowIndexing) && {
      robots: { index: false, follow: allowIndexing },
    }),
  };
}

export function absoluteUrl(path: string) {
  return new URL(path, siteUrl).toString();
}
